-- Corrections to eight investor records: seven checked against public sources,
-- plus JSW Ventures reclassified to the new CVC category.
-- Upsert: safe to re-run.

on conflict (slug) do update set name = excluded.name, type = excluded.type, tagline = excluded.tagline, description = excluded.description, website = excluded.website, city = excluded.city, state = excluded.state, sector = excluded.sector, industry = excluded.industry, stage = excluded.stage, founded = excluded.founded, founders = excluded.founders, investors = excluded.investors, funding = excluded.funding, lat = excluded.lat, lng = excluded.lng, timing = excluded.timing, status = 'live';
